using System.Collections.Generic;
using Kairo.Application.Abstractions.Meta;

namespace Kairo.Application.DTOs;

/// <summary>
/// Structured continuity state generated by the Meta Continuity Engine.
/// Returned to the caller as a standalone document.
///
/// NOT embedded in ContinuityArchive directly. Does NOT modify archive schemaVersion (stays 1.0),
/// format identifier, or SHA-256 hashing behavior.
///
/// MetaTokenUsage is defined once in Kairo.Application.Abstractions.Meta
/// and reused here and in MetaMemoryResult.
/// </summary>
public class MetaContinuityResult
{
    /// <summary>Project name inferred from the conversation.</summary>
    public string ProjectName { get; set; } = string.Empty;

    /// <summary>High-level purpose and problem the project solves.</summary>
    public string ProjectPurpose { get; set; } = string.Empty;

    /// <summary>The current active objective of the project.</summary>
    public string CurrentObjective { get; set; } = string.Empty;

    /// <summary>Key confirmed decisions that have been made and are binding going forward.</summary>
    public List<string> ImportantDecisions { get; set; } = new();

    /// <summary>Proposed decisions or suggestions from assistant awaiting user confirmation.</summary>
    public List<string> ProposedDecisions { get; set; } = new();

    /// <summary>Unresolved architectural or product questions.</summary>
    public List<string> OpenQuestions { get; set; } = new();

    /// <summary>Confirmed functional or technical requirements.</summary>
    public List<string> ConfirmedRequirements { get; set; } = new();

    /// <summary>Hard constraints and security/architectural boundaries that must be respected.</summary>
    public List<string> Constraints { get; set; } = new();

    /// <summary>Work that was completed in this conversation.</summary>
    public List<string> CompletedWork { get; set; } = new();

    /// <summary>Summary of current progress state.</summary>
    public string CurrentProgress { get; set; } = string.Empty;

    /// <summary>Tasks or roadmap phases that remain outstanding.</summary>
    public List<string> OutstandingTasks { get; set; } = new();

    /// <summary>Known blockers preventing progress.</summary>
    public List<string> Blockers { get; set; } = new();

    /// <summary>Key dependencies between systems or tasks.</summary>
    public List<string> Dependencies { get; set; } = new();

    /// <summary>The single most useful concrete next action to take.</summary>
    public string RecommendedNextAction { get; set; } = string.Empty;

    /// <summary>Technical context: stack, architecture, tools, patterns.</summary>
    public string TechnicalContext { get; set; } = string.Empty;

    /// <summary>Relevant conversation summary context.</summary>
    public string ConversationContext { get; set; } = string.Empty;

    /// <summary>Token usage as reported by the Meta API.</summary>
    public MetaTokenUsage TokenUsage { get; set; } = new();

    /// <summary>ISO-8601 timestamp of when this summary was generated.</summary>
    public string GeneratedAt { get; set; } = string.Empty;
}
